    <!-- Search mode -->
    <template v-if="isSearching">
      <!-- Search input (always visible) -->
      <div class="flex-shrink-0 px-2 py-2 border-b border-base-300">
        <ChatSearch
          @search="onSearchResults"
          @clear="closeSearch"
          @error="onSearchError"
          @no-results="onNoResults"
        />
      </div>

      <!-- Search results (scrollable) -->
      <div class="flex-1 overflow-y-auto min-h-0">
        <div class="flex flex-col gap-2 p-2">
          <div v-if="searchResultsData?.results?.length > 0">
            <ChatCard
              v-for="result in searchResultsData.results"
              :key="result.chat?.id || result.id"
              :chat="result.chat"
              :isActive="isActive(result.chat)"
              :badgeColor="badgeColor"
              :snippet="result.snippet || getLastMessageSnippet(result.chat)"
              @select="selectChat(result.chat)"
            />
          </div>

          <!-- No results state -->
          <div v-else-if="searchResultsData" class="text-center py-8 text-base-content/50">
            <i class="fa-solid fa-inbox text-3xl mb-2 block"></i>
            <p class="text-sm">No chats found</p>
          </div>
        </div>

        <!-- Pagination info -->
        <div v-if="searchResultsData" class="sticky bottom-0 text-xs text-base-content/50 text-center py-2 bg-base-100 border-t border-base-300">
          {{ searchResultsData.results?.length || 0 }} / {{ searchResultsData.total || 0 }} results
        </div>
      </div>
    </template>

    <!-- Recent chats mode -->
    <template v-else>
      <!-- Header with title and action buttons (always visible) -->
      <div v-if="recentChats.length > 0" class="flex-shrink-0 flex items-center justify-between px-2 py-2 border-b border-base-300 gap-2">
        <div class="text-[9px] font-extrabold tracking-wider text-base-content-ERROR-40 uppercase flex-1">
          {{ userFilterLabel }}
        </div>

        <!-- Action buttons -->
        <div class="flex gap-1 flex-shrink-0">
          <!-- User filter button -->
          <button
            @click="toggleUserFilterDropdown"
            class="btn btn-xs btn-ghost relative"
            :class="hasUserFilter ? 'btn-active' : ''"
            :title="hasUserFilter ? `Filter: ${selectedUserName}` : 'Filter by user'"
          >
            <i class="fa-solid fa-user text-sm"></i>
            <div v-if="hasUserFilter" class="absolute -top-1 -right-1 w-2 h-2 rounded-full bg-accent"></div>
          </button>

          <!-- Search button -->
          <button
            @click="toggleSearchMode"
            class="btn btn-xs btn-ghost"
            title="Search chats"
          >
            <i class="fa-solid fa-magnifying-glass text-sm"></i>
          </button>
        </div>
      </div>

      <!-- Empty state -->
      <div v-else class="flex-1 flex flex-col items-center justify-center text-base-content/50">
        <i class="fa-solid fa-inbox text-3xl mb-2"></i>
        <p class="text-sm">{{ noChatsMessage }}</p>
      </div>

      <!-- Scrollable chat cards container -->
      <div
        v-if="recentChats.length > 0"
        class="flex-1 overflow-y-auto min-h-0 p-2"
        @scroll="handleScroll"
      >
        <div class="flex flex-col gap-2">
          <ChatCard
            v-for="chat in recentChats"
            :key="chat.id"
            :chat="chat"
            :isActive="isActive(chat)"
            :chatProject="getChatProject(chat)"
            :badgeColor="badgeColor"
            :snippet="getLastMessageSnippet(chat)"
            @select="selectChat(chat)"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script>
export default {
  components: {
    ChatSearch,
    ChatCard
  },
  props: {
    collapsed: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      limit: 10,
      badgeColor: {
        task: 'primary',
        chat: 'accent'
      },
      isSearching: false,
      searchResultsData: null,
      selectedUserId: null,
      showUserFilterDropdown: false
    }
  },
  computed: {
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    allUsers() {
      const users = this.$storex?.users?.allUsers || []
      return users.filter(u => u?.id || u?.userName)
    },
    otherUsers() {
      return this.allUsers.filter(u => u?.id !== this.currentUser?.id)
    },
    hasUserFilter() {
      return this.selectedUserId !== null && this.selectedUserId !== undefined
    },
    selectedUserName() {
      if (!this.hasUserFilter) return null
      const user = this.allUsers.find(u => u?.id === this.selectedUserId)
      return user?.userName || 'Unknown'
    },
    userFilterLabel() {
      if (this.hasUserFilter) {
        return `Chats by ${this.selectedUserName}`
      }
      return 'Recent Chats & Tasks'
    },
    noChatsMessage() {
      if (this.hasUserFilter) {
        return `No chats from ${this.selectedUserName}`
      }
      return 'No recent chats'
    },
    allChats() {
      return this.$storex?.chats?.allChats || []
    },
    sortedChats() {
      let chats = [...this.allChats]

      // Filter by user when user filter is active
      if (this.hasUserFilter) {
        chats = chats.filter(chat => this.chatInvolvesUser(chat, this.selectedUserId))
      } else {
        // Filter by project when no user filter is active
        const activeProjectId = this.$storex?.projects?.activeProject?.project_id
        chats = chats.filter(chat => 
          chat && chat.id && (chat.project_id === activeProjectId || chat.owner_project_id === activeProjectId)
        )
      }

      // Sort by recency
      return chats.sort((a, b) => {
        const getChatTime = (c) => {
          if (c.updated_at) return new Date(c.updated_at).getTime()
          if (c.messages && c.messages.length > 0) {
            const lastMsg = c.messages[c.messages.length - 1]
            const t = lastMsg.updated_at || lastMsg.created_at
            if (t) return new Date(t).getTime()
          }
          return 0
        }
        return getChatTime(b) - getChatTime(a)
      })
    },
    recentChats() {
      return this.sortedChats.slice(0, this.limit)
    }
  },
  mounted() {
    // Initialize user filter to current user
    if (this.currentUser?.id) {
      this.selectedUserId = this.currentUser.id
    }
  },
  methods: {
    handleScroll(e) {
      const { scrollTop, clientHeight, scrollHeight } = e.target
      if (scrollHeight - scrollTop - clientHeight < 40) {
        if (this.limit < this.sortedChats.length) {
          this.limit += 10
        }
      }
    },
    getInitials(name) {
      if (!name) return 'CH'
      const cleanName = name.replace(/[^\w\s-]/g, '').trim()
      const words = cleanName.split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    isActive(chat) {
      return this.$storex?.chats?.activeChat?.id === chat.id
    },
    async selectChat(chat) {
      await this.$storex.chats.setActiveChat(chat)
    },
    getChatProject(chat) {
      const projects = this.$storex?.projects?.allProjects || this.$projects?.allProjects || []
      return projects.find(p => p.project_id === chat.project_id || p.project_id === chat.owner_project_id) || this.$project
    },
    getLastMessageSnippet(chat) {
      if (!chat.messages || chat.messages.length === 0) {
        return 'No messages'
      }
      const messagesWithContent = [...chat.messages]
        .reverse()
        .filter(m => m.content || m.think)
      if (messagesWithContent.length === 0) {
        return 'No message content'
      }
      const lastMsg = messagesWithContent[0]
      const snippet = lastMsg.content || lastMsg.think || ''
      return snippet.length > 70 ? snippet.substring(0, 70).trim() + '...' : snippet
    },
    toggleSearchMode() {
      this.isSearching = !this.isSearching
      this.showUserFilterDropdown = false
      if (!this.isSearching) {
        this.searchResultsData = null
      }
    },
    closeSearch() {
      this.isSearching = false
      this.searchResultsData = null
    },
    onSearchResults(searchData) {
      this.searchResultsData = searchData.results
    },
    onSearchError(error) {
      console.error('Search error:', error)
    },
    onNoResults() {
      this.searchResultsData = { results: [], total: 0 }
    },
    toggleUserFilterDropdown() {
      this.showUserFilterDropdown = !this.showUserFilterDropdown
    },
    toggleUserFilter() {
      if (this.hasUserFilter) {
        this.clearUserFilter()
      } else if (this.currentUser?.id) {
        this.selectedUserId = this.currentUser.id
      }
    },
    selectUserFilter(user) {
      this.selectedUserId = user?.id
      this.showUserFilterDropdown = false
      this.limit = 10
    },
    clearUserFilter() {
      this.selectedUserId = null
      this.showUserFilterDropdown = false
      this.limit = 10
    },
    chatInvolvesUser(chat, userId) {
      if (!chat || !userId) return false

      // Check if user is in profiles array
      if (chat.profiles && Array.isArray(chat.profiles)) {
        if (chat.profiles.some(p => p?.id === userId || p?.user_id === userId)) {
          return true
        }
      }

      // Check if any message is from this user
      if (chat.messages && Array.isArray(chat.messages)) {
        if (chat.messages.some(m => m?.created_by === userId || m?.user_id === userId)) {
          return true
        }
      }

      // Check if user created the chat
      if (chat.created_by === userId) {
        return true
      }

      return false
    }
  }
}
</script>
```

## Summary of Changes

| Item | Change |
|------|--------|
| **Initialization** | Added `mounted()` hook to set `selectedUserId` to current user ID on component load |
| **Filter Logic** | Updated `sortedChats` computed property - user filter now shows chats across ALL projects |
| **Toggle Method** | Added `toggleUserFilter()` method to easily toggle filter on/off in collapsed mode |
| **Filter Active** | User filter is now active by default when component loads |

The user filter is now initialized to the current user and will display all recent chats from that user across all projects, sorted by date.

