          <i :class="isSearching ? 'fa-solid fa-xmark' : 'fa-solid fa-magnifying-glass'"></i>
        </div>

        <!-- Tooltip on hover -->
        <div class="absolute left-14 top-1/2 -translate-y-1/2 bg-base-300 text-base-content text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none whitespace-nowrap z-50 border border-base-content/10">
          {{ isSearching ? 'Back to chats' : 'Search chats' }}
        </div>
      </div>

      <!-- Chat icons with counters -->
      <template v-if="!isSearching">
        <div
          v-for="chat in recentChats.slice(0, 5)"
          :key="chat.id"
          @click="selectChat(chat)"
          class="relative cursor-pointer transition-all duration-200 group"
          :title="chat.name"
        >
          <div
            class="w-10 h-10 rounded-lg flex items-center justify-center text-xs font-bold border transition-all duration-200"
            :class="isActive(chat)
              ? 'bg-primary text-primary-content border-primary/60 shadow-md ring-2 ring-primary/20'
              : 'bg-base-300 text-base-content border-base-content/10 hover:bg-base-300/80 hover:border-base-content/20'"
          >
            {{ getInitials(chat.name) }}
          </div>

          <!-- Unread badge (if available) -->
          <div v-if="chat.unread_count > 0" class="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-error text-white text-[9px] font-bold flex items-center justify-center border border-base-100">
            {{ chat.unread_count > 9 ? '9+' : chat.unread_count }}
          </div>

          <!-- Tooltip on hover -->
          <div class="absolute left-14 top-1/2 -translate-y-1/2 bg-base-300 text-base-content text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none whitespace-nowrap z-50 border border-base-content/10">
            {{ chat.name }}
          </div>
        </div>

        <!-- Show more indicator if chats exceed limit -->
        <div v-if="totalChats > 5" class="text-[9px] text-base-content-ERROR-40 mt-2">
          +{{ totalChats - 5 }}
        </div>
      </template>
    </div>
  </div>

  <!-- Full mode - shows detailed chat cards with scrollable list -->
  <div v-else class="flex flex-col w-full h-full gap-0 overflow-hidden">
    <!-- Always visible header with controls -->
    <div class="flex-shrink-0 border-b border-base-300">
      <!-- Title and filter/search buttons row -->
      <div class="flex items-center justify-between px-2 py-2 gap-2">
        <div class="text-[9px] font-extrabold tracking-wider text-base-content-ERROR-40 uppercase flex-1">
          {{ isSearching ? 'Search Results' : userFilterLabel }}
        </div>

        <!-- Action buttons -->
        <div class="flex gap-1 flex-shrink-0">
          <!-- User filter button -->
          <button
            @click="toggleUserFilterDropdown"
            class="btn btn-xs btn-ghost relative"
            :class="hasUserFilter ? 'btn-active' : ''"
            :title="hasUserFilter ? `Filter: ${selectedUserName}` : 'Filter by user'"
          >
            <i class="fa-solid fa-user text-sm"></i>
            <div v-if="hasUserFilter" class="absolute -top-1 -right-1 w-2 h-2 rounded-full bg-accent"></div>
          </button>

          <!-- Search button -->
          <button
            @click="toggleSearchMode"
            class="btn btn-xs btn-ghost"
            :class="isSearching ? 'btn-active' : ''"
            title="Search chats"
          >
            <i class="fa-solid fa-magnifying-glass text-sm"></i>
          </button>
        </div>
      </div>

      <!-- User filter dropdown (positioned absolutely) -->
      <div v-if="showUserFilterDropdown" class="absolute top-[60px] left-2 z-50 bg-base-100 border border-base-300 rounded-lg shadow-lg p-2 min-w-[200px] max-h-64 overflow-y-auto">
        <!-- Clear filter option -->
        <button
          @click="clearUserFilter"
          class="w-full text-left px-3 py-2 rounded hover:bg-base-200 text-sm flex items-center gap-2"
          :class="!hasUserFilter ? 'bg-primary/10 text-primary font-semibold' : 'text-base-content'"
        >
          <i class="fa-solid fa-xmark text-xs"></i>
          All Users
        </button>

        <div class="divider my-1"></div>

        <!-- Current user option -->
        <button
          @click="selectUserFilter(currentUser)"
          class="w-full text-left px-3 py-2 rounded hover:bg-base-200 text-sm flex items-center gap-2"
          :class="selectedUserId === currentUser?.id ? 'bg-primary/10 text-primary font-semibold' : 'text-base-content'"
        >
          <i class="fa-solid fa-user-circle text-xs"></i>
          {{ currentUser?.userName || 'You' }}
        </button>

        <div class="divider my-1"></div>

        <!-- Other users list -->
        <div class="text-xs font-semibold text-base-content/60 px-3 py-1 uppercase">Other Users</div>
        <button
          v-for="user in otherUsers"
          :key="user.id"
          @click="selectUserFilter(user)"
          class="w-full text-left px-3 py-2 rounded hover:bg-base-200 text-sm flex items-center gap-2"
          :class="selectedUserId === user.id ? 'bg-primary/10 text-primary font-semibold' : 'text-base-content'"
        >
          <i class="fa-solid fa-user text-xs"></i>
          {{ user.userName }}
        </button>

        <!-- Empty state -->
        <div v-if="otherUsers.length === 0" class="text-xs text-base-content/40 text-center py-2">
          No other users available
        </div>
      </div>

      <!-- Search input (visible only when searching) -->
      <div v-if="isSearching" class="px-2 py-2 border-t border-base-300">
        <ChatSearch
          @search="onSearchResults"
          @clear="closeSearch"
          @error="onSearchError"
          @no-results="onNoResults"
        />
      </div>
    </div>

    <!-- Content area - scrollable -->
    <div class="flex-1 overflow-y-auto min-h-0">
      <!-- Search results mode -->
      <template v-if="isSearching">
        <div class="flex flex-col gap-2 p-2">
          <div v-if="searchResultsData?.results?.length > 0">
            <ChatCard
              v-for="result in searchResultsData.results"
              :key="result.chat?.id || result.id"
              :chat="result.chat"
              :isActive="isActive(result.chat)"
              :badgeColor="badgeColor"
              :snippet="result.snippet || getLastMessageSnippet(result.chat)"
              @select="selectChat(result.chat)"
            />
          </div>

          <!-- No results state -->
          <div v-else-if="searchResultsData" class="text-center py-8 text-base-content/50">
            <i class="fa-solid fa-inbox text-3xl mb-2 block"></i>
            <p class="text-sm">No chats found</p>
          </div>
        </div>

        <!-- Pagination info -->
        <div v-if="searchResultsData" class="sticky bottom-0 text-xs text-base-content/50 text-center py-2 bg-base-100 border-t border-base-300">
          {{ searchResultsData.results?.length || 0 }} / {{ searchResultsData.total || 0 }} results
        </div>
      </template>

      <!-- Recent chats mode -->
      <template v-else>
        <!-- Empty state -->
        <div v-if="recentChats.length === 0" class="flex flex-col items-center justify-center h-full text-base-content/50">
          <i class="fa-solid fa-inbox text-3xl mb-2"></i>
          <p class="text-sm">{{ noChatsMessage }}</p>
        </div>

        <!-- Chat cards list -->
        <div v-else class="flex flex-col gap-2 p-2">
          <ChatCard
            v-for="chat in recentChats"
            :key="chat.id"
            :chat="chat"
            :isActive="isActive(chat)"
            :chatProject="getChatProject(chat)"
            :badgeColor="badgeColor"
            :snippet="getLastMessageSnippet(chat)"
            @select="selectChat(chat)"
          />

          <!-- Loading indicator for pagination -->
          <div v-if="isLoadingMore" class="flex justify-center py-4">
            <span class="loading loading-spinner loading-sm"></span>
          </div>

          <!-- End of list indicator -->
          <div v-if="!hasMoreChats && recentChats.length > 0" class="text-center text-xs text-base-content/40 py-4">
            No more chats
          </div>
        </div>
      </template>
    </div>

    <!-- Scroll handler container -->
    <div
      class="hidden"
      @scroll="handleScroll"
      ref="scrollContainer"
    ></div>
  </div>
</template>

<script>
export default {
  components: {
    ChatSearch,
    ChatCard
  },
  props: {
    collapsed: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      pageSize: 10,
      currentPage: 1,
      totalChats: 0,
      badgeColor: {
        task: 'primary',
        chat: 'accent'
      },
      isSearching: false,
      searchResultsData: null,
      selectedUserId: null,
      showUserFilterDropdown: false,
      recentChats: [],
      isLoadingMore: false,
      hasMoreChats: true
    }
  },
  computed: {
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    allUsers() {
      const users = this.$storex?.users?.allUsers || []
      return users.filter(u => u?.id || u?.userName)
    },
    otherUsers() {
      return this.allUsers.filter(u => u?.id !== this.currentUser?.id)
    },
    hasUserFilter() {
      return this.selectedUserId !== null && this.selectedUserId !== undefined
    },
    selectedUserName() {
      if (!this.hasUserFilter) return null
      const user = this.allUsers.find(u => u?.id === this.selectedUserId)
      return user?.userName || 'Unknown'
    },
    userFilterLabel() {
      if (this.hasUserFilter) {
        return `Chats by ${this.selectedUserName}`
      }
      return 'Recent Chats & Tasks'
    },
    noChatsMessage() {
      if (this.hasUserFilter) {
        return `No chats from ${this.selectedUserName}`
      }
      return 'No recent chats'
    }
  },
  mounted() {
    if (this.currentUser?.id) {
      this.selectedUserId = this.currentUser.id
    }
    this.loadRecentChats()
  },
  methods: {
    async loadRecentChats(append = false) {
      try {
        this.isLoadingMore = true
        const response = await this.$chats.getRecentChats({
          userId: this.selectedUserId || undefined,
          page: this.currentPage,
          pageSize: this.pageSize
        })

        if (response.error) {
          console.error('Error loading recent chats:', response.error)
          this.isLoadingMore = false
          return
        }

        this.totalChats = response.total

        if (append) {
          this.recentChats.push(...response.chats)
        } else {
          this.recentChats = response.chats
        }

        this.hasMoreChats = response.has_next
        this.isLoadingMore = false
      } catch (error) {
        console.error('Error loading recent chats:', error)
        this.isLoadingMore = false
      }
    },
    async handleScroll(e) {
      const { scrollTop, clientHeight, scrollHeight } = e.target
      if (scrollHeight - scrollTop - clientHeight < 100 && this.hasMoreChats && !this.isLoadingMore) {
        this.currentPage += 1
        await this.loadRecentChats(true)
      }
    },
    getInitials(name) {
      if (!name) return 'CH'
      const cleanName = name.replace(/[^\w\s-]/g, '').trim()
      const words = cleanName.split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    isActive(chat) {
      return this.$storex?.chats?.activeChat?.id === chat.id
    },
    async selectChat(chat) {
      await this.$storex.chats.setActiveChat(chat)
    },
    getChatProject(chat) {
      const projects = this.$storex?.projects?.allProjects || this.$projects?.allProjects || []
      return projects.find(p => p.project_id === chat.project_id || p.project_id === chat.owner_project_id) || this.$project
    },
    getLastMessageSnippet(chat) {
      if (!chat.messages || chat.messages.length === 0) {
        return 'No messages'
      }
      const messagesWithContent = [...chat.messages]
        .reverse()
        .filter(m => m.content || m.think)
      if (messagesWithContent.length === 0) {
        return 'No message content'
      }
      const lastMsg = messagesWithContent[0]
      const snippet = lastMsg.content || lastMsg.think || ''
      return snippet.length > 70 ? snippet.substring(0, 70).trim() + '...' : snippet
    },
    toggleSearchMode() {
      this.isSearching = !this.isSearching
      this.showUserFilterDropdown = false
      if (!this.isSearching) {
        this.searchResultsData = null
      }
    },
    closeSearch() {
      this.isSearching = false
      this.searchResultsData = null
    },
    onSearchResults(searchData) {
      this.searchResultsData = searchData.results
    },
    onSearchError(error) {
      console.error('Search error:', error)
    },
    onNoResults() {
      this.searchResultsData = { results: [], total: 0 }
    },
    toggleUserFilterDropdown() {
      this.showUserFilterDropdown = !this.showUserFilterDropdown
    },
    async toggleUserFilter() {
      if (this.hasUserFilter) {
        await this.clearUserFilter()
      } else if (this.currentUser?.id) {
        this.selectedUserId = this.currentUser.id
        await this.resetAndReload()
      }
    },
    async selectUserFilter(user) {
      this.selectedUserId = user?.id
      this.showUserFilterDropdown = false
      await this.resetAndReload()
    },
    async clearUserFilter() {
      this.selectedUserId = null
      this.showUserFilterDropdown = false
      await this.resetAndReload()
    },
    async resetAndReload() {
      this.currentPage = 1
      this.hasMoreChats = true
      this.recentChats = []
      await this.loadRecentChats()
    }
  }
}
</script>
```

## Key Changes Made

1. **Fixed Header** - Search and filter buttons are now in a persistent header that's always visible
2. **Search Input** - Moved to header and only appears when in search mode
3. **Filter Dropdown** - Positioned absolutely within the header area
4. **Scrollable Content** - Content area takes remaining space with proper overflow handling
5. **Title Updates** - Header title changes based on current mode (Search Results vs Recent Chats)
6. **Improved Layout** - Better separation between controls and content

